<?php declare(strict_types=1);if(!defined('ABSPATH')){exit;}?><div class="atlas-preview-wrap"><div class="atlas-shell"><main class="atlas-resource-main"><p class="atlas-eyebrow"><?php echo esc_html__('Patient packets','atlas-platform');?></p><h1><?php echo esc_html__('Packet builder','atlas-platform');?></h1><section class="atlas-admin-panel"><h2><?php echo esc_html__('Create packet','atlas-platform');?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="atlas-authoring-form"><input type="hidden" name="action" value="atlas_create_packet"><?php wp_nonce_field('atlas_create_packet');?><label><?php echo esc_html__('Packet name','atlas-platform');?><input required maxlength="255" name="name"></label><label><?php echo esc_html__('Description','atlas-platform');?><textarea rows="3" name="description"></textarea></label><label><?php echo esc_html__('Resource IDs, one per line','atlas-platform');?><textarea rows="5" name="items"></textarea></label><p><button class="button button-primary"><?php echo esc_html__('Save packet','atlas-platform');?></button></p></form></section><section class="atlas-admin-panel"><h2><?php echo esc_html__('Saved packets','atlas-platform');?></h2><div class="atlas-library-list"><?php foreach($packets as$packet):?><article class="atlas-library-row"><div><h2><a href="<?php echo esc_url(add_query_arg(['page'=>'atlas-packets','packet_id'=>(string)$packet['id']],admin_url('admin.php')));?>"><?php echo esc_html((string)$packet['name']);?></a></h2><p><?php echo esc_html(sprintf(__('Status: %s. Items: %d. Updated %s','atlas-platform'),(string)$packet['status'],(int)($packet['item_count']??0),(string)$packet['updated_at']));?></p></div><button class="button" type="button" onclick="window.print()"><?php echo esc_html__('Print','atlas-platform');?></button></article><?php endforeach;?></div></section><?php if($selected!==null):$packet=$selected['packet'];?><section class="atlas-admin-panel"><h2><?php echo esc_html((stri